package main

import (
	"bufio"
	"fmt"
	"os"
)

// Person は名前を持つ構造体です
type Person struct {
	Name string
}

// Employee は Person を「持つ」構造体です (has-a)
type Employee struct {
	Person  Person
	Company string
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	name := sc.Text()
	sc.Scan()
	company := sc.Text()

	// ここから下を書く: Employee を作り、
	// 「<名前> は <会社名> の社員です」と出力する
	_ = name
	_ = company
	_ = fmt.Println
}

exercise.answer:
// lesson22 ch01 解答
package main

import (
	"bufio"
	"fmt"
	"os"
)

type Person struct {
	Name string
}

type Employee struct {
	Person  Person
	Company string
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	name := sc.Text()
	sc.Scan()
	company := sc.Text()

	// 継承の代わりに、Employee が Person をフィールドとして持ちます (has-a)。
	// 「Employee は Person である」ではなく「Employee は Person を持つ」と
	// 考えるのが Go の設計スタイルです。
	e := Employee{Person: Person{Name: name}, Company: company}
	fmt.Println(e.Person.Name, "は", e.Company, "の社員です")
}
